def auth_user(info):
    username = info.get("username", "")
    if not username or not INTERNAL_AUTH_SECRET:
        abort(400, "invalid credentials")
    token = hmac.new(INTERNAL_AUTH_SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()
    return token

